from collections import Counter

def combine_dictionaries(dict1, dict2):
    return dict(Counter(dict1) + Counter(dict2))

dict1 = {'a': 100, 'b': 200, 'c':300}
dict2 = {'a': 300, 'b': 200, 'd':400}
print(combine_dictionaries(dict1, dict2))  # Output: {'a': 400, 'b': 400, 'c': 300, 'd': 400}

def count_occurrences(lst, element):
    return lst.count(element)

my_list = [1, 4, 2, 4, 5, 4]
print(count_occurrences(my_list, 4))  # Output: 3

def list_difference(list1, list2):
    return list(set(list1) - set(list2))

list1 = [1, 2, 3, 4]
list2 = [2, 4]
print(list_difference(list1, list2))  # Output: [1, 3]

def merge_and_combine(dict1, dict2):
    merged = defaultdict(list)
    for d in [dict1, dict2]:
        for key, value in d.items():
            merged[key].append(value)
    return dict(merged)

dict1 = {'a': 1, 'b': 2}
dict2 = {'b': 3, 'c': 4}
print(merge_and_combine(dict1, dict2))  # Output: {'a': [1], 'b': [2, 3], 'c': [4]}

def merge_dictionaries(dict1, dict2):
    return {**dict1, **dict2}

dict1 = {'a': 1, 'b': 2}
dict2 = {'c': 3, 'd': 4}
print(merge_dictionaries(dict1, dict2))  # Output: {'a': 1, 'b': 2, 'c': 3, 'd': 4}
